\usepackage{amssymb}
\usepackage{cancel}
\usepackage{enumerate}
\usetikzlibrary{calc}

\begin{document}

	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\pagestyle{empty}

	% Set the overall layout of the tree
	\tikzstyle{level 1}=[level distance=2.5cm, sibling distance=2.5cm]
	\tikzstyle{level 2}=[level distance=2.2cm, sibling distance=1.25cm]

	% Define styles for bags and leafs
	\tikzstyle{str} = [circle, deepskyblue, fill, inner sep=-1pt, outer sep=3pt]
	\tikzstyle{bag} = [text centered]
	%\tikzstyle{end} = [circle, minimum width=3pt,fill, inner sep=0pt]
	\tikzstyle{edge} = [scale=0.85]

	\begin{tikzpicture}[
	scale=1.3,
	grow = right,
	edge from parent/.style = {draw, color=deepskyblue, thick, -latex},
	every node/.style = {font=\small, black},
	]
	\node[] (R) {$f(x,y)$}
	child {
		node[bag] (B) {$y(t)$}        
		child {
			node[bag, label={right=5pt: \footnotesize $\dfrac{\partial f}{\partial y}\cdot \dfrac{\textrm{d} y}{\textrm{d} t}$}
			] (BB) {$t$}
			edge from parent node[edge, below] {$\dfrac{\textrm{d} y}{\textrm{d} t}$}
		}
		edge from parent node[edge, below left] {$\dfrac{\partial f}{\partial y}$}
	}
	child {
		node[bag] (T) {$x(t)$}        
		child {
			node[bag, label={right=5pt: \footnotesize $\dfrac{\partial f}{\partial x}\cdot \dfrac{\textrm{d} x}{\textrm{d} t}$}
			] (TB) {$t$}
			edge from parent node[edge, above] {$\dfrac{\textrm{d} x}{\textrm{d} t}$}
		}
		edge from parent node[edge, above left] {$\dfrac{\partial f}{\partial x}$}
	};

	%                                              TT(top top)
	%                                        <                 
	%                     T(top)               TB(top bottom)
	%  R(root)  <                 
	%                     B(bottom)         BT(bottom top)
	%                                        <                 
	%                                              BB(bottom bottom)

	%\draw[color=orangepeel, line width=5mm, line cap=round, opacity=0.1, rounded corners=2pt, 
	shorten <               = -1mm, shorten >= -1mm] 
	(R.center) -- (B.center) -- (BT.center);

	\end{tikzpicture}
\end{document}

